function getChartData(){const comparison=state.compare!==null,s=stations[state.selected],m=comparison?metricMeta.level:metricMeta[state.metric],now=Date.now(),hours=parseInt(state.range),labels=Array.from({length:25},(_,i)=>state.scenario.active?i*5+' 分':new Date(now-(24-i)*hours*3600000/24).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}));const indexes=comparison?[state.selected,state.compare]:[state.selected];const datasets=indexes.map((index,j)=>{const records=chartSeries(index);return {label:stations[index].name,stationIndex:index,records,data:records.map(h=>h?+(comparison?h.level-stations[index].limit:h[state.metric]).toFixed(2):null),borderColor:j?'#966b9c':m.color,backgroundColor:j?'transparent':m.color+'16',borderWidth:2,fill:!comparison,tension:.3,pointRadius:0,pointHoverRadius:4,pointHitRadius:14,...(j?{borderDash:[6,4]}:{})}});if(comparison||state.metric==='level')datasets.push({label:comparison?'各自教学阈值':'教学阈值',reference:true,data:labels.map(()=>comparison?0:s.limit),borderColor:'#b88068',borderWidth:1,borderDash:[4,5],pointRadius:0,fill:false});return {labels,values:datasets[0].data,datasets}}
