function makeChart(){if(typeof Chart==='undefined'){const el=$('.chart-area');if(el)el.innerHTML='<p class="article-tip">曲线暂不可用，可查看地点读数与表格。</p>';return}const canvas=$('#trend-chart');if(!canvas)return;const font=chartFontFamily(),comparison=state.compare!==null;state.chart=new Chart(canvas.getContext('2d'),{type:'line',data:getChartData(),options:{responsive:true,maintainAspectRatio:false,animation:false,interaction:{mode:'index',intersect:false},plugins:{legend:{display:comparison,labels:{color:'#4c7476',font:{family:font,size:14},filter:item=>!item.text.includes('阈值')}},tooltip:{backgroundColor:'#fafff8',titleColor:'#2a5156',bodyColor:'#2a5156',borderColor:'#aacfc9',borderWidth:1,padding:14,titleFont:{family:font,size:16},bodyFont:{family:font,size:15},callbacks:{title:items=>'模拟时刻 · '+(items[0]?.label||''),label:c=>`${c.dataset.label}：${fmt(c.parsed.y,state.metric==='flow'&&!comparison?0:2)} ${comparison?'m（相对阈值）':metricMeta[state.metric].unit}`,afterLabel:c=>{const h=c.dataset.records?.[c.dataIndex];if(!h)return '';const s=stations[c.dataset.stationIndex];return [`水位 ${fmt(h.level)} m · 流量 ${fmt(h.flow,0)} m³/s`,`pH ${fmt(h.ph,1)} · ${Hydro.stages[Hydro.stage(h.level,s.limit)].name}`]}}}},scales:{x:{grid:{display:false},border:{display:false},ticks:{maxTicksLimit:6,maxRotation:0,color:'#5e7f7d',font:{family:font,size:15},padding:7}},y:{border:{display:false},grid:{color:'#dfeae3',drawTicks:false},ticks:{maxTicksLimit:5,color:'#5e7f7d',font:{family:font,size:15},padding:9},...(!comparison&&state.metric==='ph'?{min:6.5,max:8}:{})}}}});syncChartControls()}
