function refreshChartControls(){state.chart?.destroy();makeChart()}
function updateTableReadings(){const rows=$$('#station-table-body tr');for(const row of rows){const s=stations[+row.dataset.tableStation];if(!s)continue;row.classList.toggle('selected',s.index===state.selected);const b=$('[data-station]',row);b?.setAttribute('aria-pressed',String(s.index===state.selected));row.cells[1].textContent=fmt(s.level)+' m';row.cells[2].textContent=fmt(s.flow,0)+' m³/s · pH '+fmt(s.ph,1);row.cells[3].innerHTML=stageBadge(s)}}
function updateReadings(){if(state.page!=='monitor'||state.monitorTool==='pollution')return;if(state.monitorTool==='records'){const body=$('#monitor-ledger-body'),snapshot=JSON.stringify(getMonitorRecords());if(body&&body.dataset.snapshot!==snapshot&&!body.contains(document.activeElement)){body.innerHTML=ledgerHTML(state.monitorRecordFilter);body.dataset.snapshot=snapshot}return}const stationSelect=$('#station-select');if(stationSelect)stationSelect.value=state.selected;const sourceLabel=$('#monitor-data-source');if(sourceLabel)sourceLabel.textContent=monitorDataSource();const detail=$('#map-detail');if(detail)detail.innerHTML=mapDetail();geographicController?.update(visibleStations(),state.selected);for(const b of $$('.point-choice')){const s=stations[+b.dataset.station],st=stageInfo(s),active=s.index===state.selected;b.classList.remove('calm','watch','high','critical');b.classList.add(st.key);b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active));b.setAttribute('aria-label',s.name+'，'+st.name);const dot=$('.point-number',b);if(dot)dot.className='point-number hydro-dot '+st.key;const mark=$('.point-stage',b);if(mark)mark.textContent=st.rank?st.name:''}updateTableReadings();updateMapAlerts();const summary=$('#hydro-overview');if(summary)summary.innerHTML=monitorSummary();if(state.chart){const data=getChartData();state.chart.data.labels=data.labels;state.chart.data.datasets=data.datasets;state.chart.update('none');syncChartControls()}const body=$('#monitor-ledger-body');const ledgerSnapshot=JSON.stringify(getMonitorRecords());if(body&&body.dataset.snapshot!==ledgerSnapshot&&!body.contains(document.activeElement)){body.innerHTML=ledgerHTML(state.monitorRecordFilter);body.dataset.snapshot=ledgerSnapshot;}const count=$('#ledger-count');if(count)count.textContent=hydroLedger.list().length;updateSandboxUI()}
function tick(){if(state.paused||document.hidden)return;state.tick++;if(state.scenario.active){if(!state.scenario.playing||state.page!=='monitor')return;state.scenario.minute=Math.min(120,state.scenario.minute+5);if(state.scenario.minute===120)state.scenario.playing=false;const sample=hydroModel.sample(state.scenario);stations.forEach((s,i)=>Object.assign(s,{level:sample[i].level,flow:sample[i].flow}));}else stations.forEach((s,i)=>{s.level=+(s.base+Math.sin(state.tick*.24+i)*.045).toFixed(2);s.flow=Math.max(0,Math.round(s.flowBase*(1+Math.sin(state.tick*.3+i)*.025)));s.ph=+([7.2,7.4,7.1,7.3,7.2,7.5,7.3,7.1][i]+Math.sin(state.tick*.16+i)*.04).toFixed(2)});stations.forEach((s,i)=>{histories[i].push({level:s.level,flow:s.flow,ph:s.ph});histories[i].shift()});syncScenarioEvents();updateReadings()}
function revealSelectedPoint(){const list=$('#point-choices');if(!list||!matchMedia('(max-width:760px)').matches)return;const selected=$('.point-choice[aria-pressed="true"]',list);if(!selected)return;const frame=list.getBoundingClientRect(),item=selected.getBoundingClientRect();if(item.left<frame.left+2)list.scrollLeft+=item.left-frame.left-2;else if(item.right>frame.right-2)list.scrollLeft+=item.right-frame.right+2}
function selectStation(i,scroll=false,fromMap=false){if(!stations[i])return;const previous=state.selected;if(state.compare===i)state.compare=previous;state.selected=i;updateReadings();revealSelectedPoint();geographicController?.select(i,!fromMap);const info=$('#geo-location-info');if(info&&info.dataset.place!==String(i)){info.innerHTML=stationContext();info.dataset.place=i}const profile=$('#station-profile-copy');if(profile)profile.innerHTML=stationProfileHTML();const inspect=$('.monitor-selection-tools [data-inspect]');if(inspect)inspect.dataset.inspect=i;const compare=$('#compare-station');if(compare)compare.innerHTML=`<option value="">不对比</option>${stations.filter(s=>s.index!==i).map(s=>`<option value="${s.index}" ${state.compare===s.index?'selected':''}>${s.name}</option>`).join('')}`;if(state.chart){state.chart.destroy();makeChart()}if(scroll){const target=$('#map-detail');target?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});if(navigationByKeyboard&&target){target.tabIndex=-1;target.focus({preventScroll:true})}}}

function stageInfo(s){const rank=Hydro.stage(s.level,s.limit);return {...Hydro.stages[rank],rank}}
function stageBadge(s){const st=stageInfo(s);return `<span class="hydro-status ${st.key}"><b aria-hidden="true">${st.symbol}</b>${st.name}</span>`}
function pointCards(){return visibleStations().map(s=>`<button class="point-choice ${stageInfo(s).key} ${state.selected===s.index?'selected':''}" data-station="${s.index}" aria-pressed="${state.selected===s.index}" aria-label="${s.name}，${stageInfo(s).name}"><span class="point-number hydro-dot ${stageInfo(s).key}">${s.index+1}</span><strong>${s.name}</strong><span class="point-stage">${stageInfo(s).rank?stageInfo(s).name:''}</span></button>`).join('')}
function monitorStationOptions(){return visibleStations().map(s=>`<option value="${s.index}" ${state.selected===s.index?'selected':''}>${s.name}</option>`).join('')}
function monitorDataSource(){if(state.scenario.active&&stations[state.selected].group!==state.scenario.scope)return '初始教学读数 · 该地点未参与本轮降雨推演';return state.scenario.active?`降雨推演结果 · 第${state.scenario.minute}分钟 · ${groupNames[state.scenario.scope]}`:`初始教学读数 · ${state.paused?'已暂停':'每3秒模拟更新'}`}
function mapPanel(){return `<section class="monitor-location-panel" aria-label="地点与模拟水情"><div class="monitor-location-filters"><label for="region-select"><span>水域</span>${regionSelect()}</label><label for="station-select"><span>地点</span><select id="station-select" aria-label="选择教学地点">${monitorStationOptions()}</select></label><span class="monitor-region-summary">${visibleStations().length}个地点 · ${mapWarnings().length}处模拟超阈</span></div><div class="monitor-map-grid"><div class="monitor-map-stage"><div class="atlas-toolbar"><h3>河湖地图</h3><div class="atlas-controls"><div role="group" aria-label="地图样式"><button data-map-mode="water" aria-pressed="${state.mapMode==='water'}">水系</button><button data-map-mode="streets" aria-pressed="${state.mapMode==='streets'}">街道</button></div><button id="map-fit" class="atlas-reset">全景</button></div></div><div class="geographic-map" id="river-map" aria-label="南京真实地理与教学地点"></div><p class="geo-status" id="geo-status" role="status">正在载入水系…</p><div class="monitor-map-footer"><div class="map-legend" aria-label="教学状态图例">${Hydro.stages.map(st=>`<span class="${st.key}"><b>${st.symbol}</b>${st.name}</span>`).join('')}</div><details class="layer-menu"><summary>图层</summary><div>${[['water','河流水系'],['alerts','预警标记'],['lakes','湖泊轮廓']].map(([key,label])=>`<label><input type="checkbox" data-hydro-layer="${key}" aria-label="${label}" ${state.layers[key]?'checked':''}>${label}</label>`).join('')}</div></details><button class="source-link" id="open-data-sources">来源</button></div></div><aside class="monitor-selection-panel"><div class="selected-water" id="map-detail">${mapDetail()}</div><div class="monitor-selection-tools"><button class="btn" data-inspect="${state.selected}">${icon('scan')}打开 AI 照片识别</button><div class="monitor-selection-meta"><details class="monitor-reading-help" data-card-title="读数与状态说明"><summary>读数说明</summary><p><b>水位（m）</b>是相对该地点基准的水面高度。不同地点的基准可能不同，不能直接据此排名。</p><p><b>流量（m³/s）</b>是每秒通过断面的水量；<b>pH</b>是酸碱程度，不能单独判定水质安全。</p><p><b>教学阈值</b>是演示用的比较值。标为“模拟超阈”表示读数达到该值，不是官方预警等级。读数来自初始演示或你设置的降雨推演，来源显示在页面上方。</p></details><details class="station-profile"><summary>地点资料</summary><div id="station-profile-copy">${stationProfileHTML()}</div><div class="geo-location-info" id="geo-location-info" data-place="${state.selected}">${stationContext()}</div></details></div></div></aside></div></section>`}
function mapDetail(){const s=stations[state.selected],margin=s.limit-s.level;return `<div class="selected-water-heading"><div><span class="monitor-card-eyebrow">当前地点</span><h2>${s.name}</h2></div>${stageBadge(s)}</div><div class="water-readings"><div><span>模拟水位</span><strong>${fmt(s.level)}<small>m</small></strong></div><div><span>模拟流量</span><strong>${fmt(s.flow,0)}<small>m³/s</small></strong></div><div><span>模拟 pH</span><strong>${fmt(s.ph,1)}</strong></div></div><p class="threshold-distance">${margin>=0?'距教学阈值':'超过教学阈值'} <strong>${fmt(Math.abs(margin))} m</strong></p>`}
function miniTrend(index){const values=(state.scenario.active?chartSeries(index).filter(Boolean):histories[index]).map(h=>h.level),min=Math.min(...values)-.1,max=Math.max(...values)+.1;return `<svg viewBox="0 0 220 48" role="img" aria-label="最近模拟水位走势"><path d="${values.map((v,i)=>`${i?'L':'M'}${i/Math.max(1,values.length-1)*220},${44-(v-min)/(max-min)*40}`).join(' ')}" fill="none" stroke="${stageInfo(stations[index]).color}" stroke-width="2" vector-effect="non-scaling-stroke"/></svg>`}
function stationProfileHTML(){const s=stations[state.selected],p=Hydro.profiles[s.index];return `<h3>${p.kind}</h3><p>${p.description}</p><p>${p.fact}</p><button class="source-link" data-article="${p.article}">阅读相关文章 <svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-right"></use></svg></button><p>教学阈值 ${fmt(s.limit)} m；坐标来源见下方。非官方水文站档案。</p>`}
function mapPopupHTML(index){const s=stations[index],margin=s.level-s.limit;return `<div class="hydro-map-popup ${stageInfo(s).key}"><strong>${escapeHTML(s.name)}</strong>${stageBadge(s)}<div class="popup-level">${fmt(s.level)} <small>m · 模拟水位</small></div><p class="popup-threshold ${isWarn(s)?'is-over':''}">${margin>=0?'超出':'低于'}教学阈值 <b>${fmt(Math.abs(margin))} m</b></p>${miniTrend(index)}<div class="popup-actions"><button data-map-details="${index}">水情详情</button><button data-inspect="${index}">AI 巡检 ${icon('scan')}</button></div></div>`}
function mapWarnings(){return visibleStations().filter(s=>Hydro.stage(s.level,s.limit)>=2).sort((a,b)=>Hydro.stage(b.level,b.limit)-Hydro.stage(a.level,a.limit)||(b.level-b.limit)-(a.level-a.limit))}
function mapWarningKey(){return mapWarnings().map(s=>s.index+':'+stageInfo(s).rank).join('|')}
function mapAlertsHTML(){const warnings=mapWarnings();return `<div class="alarm-summary"><span>模拟预警</span><strong>${String(warnings.length).padStart(2,'0')}<small>处超阈</small></strong></div><div class="alarm-feed">${warnings.length?warnings.map(s=>`<button data-map-alert="${s.index}" class="${stageInfo(s).key}" aria-label="定位${s.name}，${stageInfo(s).name}，超过教学阈值${fmt(s.level-s.limit)}米"><span class="alarm-signal" aria-hidden="true">${icon('warning')}</span><span class="alarm-place"><b>${s.name}</b><span class="alarm-stage">${stageInfo(s).name}</span></span><span class="alarm-reading"><strong><span class="alarm-level-value">${fmt(s.level)}</span><small> m</small></strong><span class="alarm-margin">超出 ${fmt(s.level-s.limit)} m</span></span><span class="alarm-locate">${icon('pin')}<span>定位</span></span></button>`).join(''):`<div class="alarm-empty">${icon('shield')}<span>当前水域暂无模拟超阈</span></div>`}</div>`}
function updateMapAlerts(){const el=$('#map-alerts');if(!el)return;const warnings=mapWarnings(),structure=mapWarningKey(),signature=warnings.map(s=>s.index+':'+stageInfo(s).rank).sort().join('|');
 if(el.dataset.structure!==structure){const selected=document.activeElement?.closest?.('[data-map-alert]')?.dataset.mapAlert;el.innerHTML=mapAlertsHTML();el.dataset.structure=structure;if(selected!==undefined)$(`[data-map-alert="${selected}"]`,el)?.focus({preventScroll:true})}
 else for(const s of warnings){const button=$(`[data-map-alert="${s.index}"]`,el);if(!button)continue;$('.alarm-level-value',button).textContent=fmt(s.level);$('.alarm-margin',button).textContent='超出 '+fmt(s.level-s.limit)+' m';button.setAttribute('aria-label',`定位${s.name}，${stageInfo(s).name}，超过教学阈值${fmt(s.level-s.limit)}米`)}
 el.classList.toggle('has-alerts',!!signature);el.classList.toggle('has-critical',warnings.some(s=>stageInfo(s).rank===3));if(state.mapWarningSignature!==undefined&&state.mapWarningSignature!==signature){const live=$('#map-alert-live');if(live)live.textContent=signature?warnings.map(s=>s.name+'，'+stageInfo(s).name).join('；'):'本水域已无模拟超阈地点。'}state.mapWarningSignature=signature}
function monitorSummary(){const list=visibleStations(),near=list.reduce((a,b)=>a.limit-a.level<b.limit-b.level?a:b);return `${state.scenario.active?`<span class="scenario-position">教学推演 ${state.scenario.minute} / 120 分</span>`:''}<span><b>${list.length}</b> 个教学地点</span><span>${isWarn(near)?'超阈最多':'距阈值最近'}：<b>${near.name}</b></span><span class="monitor-update"><i></i>模拟更新 <time>${timeString(new Date())}</time></span>`}
const monitorTools=[['water','水情总览'],['rain','降雨推演'],['pollution','污染扩散'],['records','事件记录']];
function monitorToolTabs(){return `<div class="monitor-tool-tabs" role="tablist" aria-label="看水情工作区">${monitorTools.map(([key,name])=>`<button type="button" id="monitor-tool-${key}" role="tab" data-monitor-tool="${key}" aria-selected="${state.monitorTool===key}" aria-controls="monitor-tool-panel" tabindex="${state.monitorTool===key?0:-1}">${name}</button>`).join('')}</div>`}
function renderMonitorOverview(){if(!visibleStations().includes(stations[state.selected]))state.region=stations[state.selected].group;return `<div class="monitor-workspace-intro monitor-overview-intro"><div><h2>水情总览</h2><p id="monitor-data-source">${monitorDataSource()}</p></div><div class="monitor-workspace-actions">${state.scenario.active?`<button class="btn" data-sandbox="reset">恢复初始读数</button>`:`<button class="btn" id="toggle-live">${state.paused?'继续演示':'暂停演示'}</button>`}<button class="btn" id="export-csv">导出读数</button></div></div>${mapPanel()}${chartPanel()}<div class="monitor-analysis-links"><a class="monitor-analysis-link" href="#/monitor?view=compare"><div><strong>对比两个地点</strong><span>看两个地点离各自阈值还有多远。</span></div>${icon('arrow')}</a><a class="monitor-analysis-link" href="#/monitor?view=table"><div><strong>查看地点数据表</strong><span>集中查看当前水域的读数，或选择地点返回地图。</span></div>${icon('arrow')}</a></div>`}
function renderMonitorRain(){if(state.scenario.active)state.region=state.scenario.scope;else if(state.region==='all')state.region='qinhuai';const scope=state.scenario.active?state.scenario.scope:state.region;if(stations[state.selected].group!==scope)state.selected=Hydro.network[scope].order[0];return `<div class="monitor-workspace-intro"><div><h2>降雨推演</h2><p>先设置雨强与闸门，再播放时间轴，查看各地点的响应。</p></div><label class="monitor-rain-region" for="region-select"><span>推演水域</span><select id="region-select" aria-label="选择推演水域">${['qinhuai','yangtze','lake'].map(key=>`<option value="${key}" ${state.region===key?'selected':''}>${groupNames[key]}</option>`).join('')}</select></label></div>${sandboxHTML()}<div class="monitor-task-footer"><button class="btn" data-monitor-tool="water">在地图查看当前结果 ${icon('arrow')}</button><button class="btn" data-monitor-tool="records">查看事件记录 ${icon('arrow')}</button></div>`}
function renderMonitorRecords(){const all=getMonitorRecords(),pending=hydroLedger.pendingCount();return `<div class="monitor-workspace-intro"><div><h2>事件记录</h2><p>水位预警、照片巡检与污染推演统一保存在当前浏览器。</p></div><span class="monitor-record-summary">${all.length}条记录 · ${pending}条待核查</span></div><div class="monitor-record-filters" role="group" aria-label="记录类型">${[['all','全部'],['water','水位预警'],['inspection','照片巡检'],['pollution','污染推演']].map(([key,name])=>`<button type="button" data-monitor-record-filter="${key}" aria-pressed="${state.monitorRecordFilter===key}">${name}<span>${all.filter(r=>key==='all'||r.type===key).length}</span></button>`).join('')}</div><section class="monitor-record-panel panel"><div id="monitor-ledger-body">${ledgerHTML(state.monitorRecordFilter)}</div></section>`}

function monitorHelpDetails(key){const helps={
 water:{purpose:'选地点，看对应的读数和地图。',title:'怎么看水情',body:'<p><b>先选地点。</b>水域决定地点范围，选择地点或点击地图标记后，读数和趋势会同步切换。</p><p><b>再看读数。</b>水位是相对该地点基准的高度；流量是每秒通过的水量；pH表示酸碱程度。它们不是同一个指标，pH也不能单独判断水质是否安全。</p><p><b>需要进一步分析时。</b>“对比两个地点”和“数据表”会进入独立页面；“图层”只改变地图显示。“打开 AI 照片识别”会跳转并预填当前地点。自动变化是教学演示，不是实时传感器。</p>'},
 rain:{purpose:'设置参数，再播放模拟时间，看水位怎样变化。',title:'降雨推演怎么操作',body:'<p><b>1. 设置雨强和闸门。</b>雨强的mm/h表示一小时的降雨厚度。点击预设会准备一轮新的推演，时间仍停在0分。</p><p><b>2. 点击“播放推演”。</b>时间轴是压缩后的模拟时间，不需要真实等待两小时。可以暂停、前进10分钟或拖动回看；右侧曲线对应当前选中的地点。</p><p><b>3. 比较变化。</b>调闸会逐步降低起点水位，后续地点可能承接更多来水。灰色虚线是同场降雨下未调闸的对照。0%表示关闭、100%表示全开，这里不连接真实设备。</p>'},
 pollution:{purpose:'设释放点，再播放，观察污染沿河经过哪些位置。',title:'污染扩散怎么操作',body:'<p><b>1. 设置一次假设释放。</b>选择河段、释放位置和质量；也可以点击“在地图上设释放点”，再点击河道附近。</p><p><b>2. 播放或拖动模拟时间。</b>彩色线表示沿河浓度与设定阈值的比较，不表示陆地受污染范围。“扩散强度”越大，同一团污染越分散，峰值通常越低。</p><p><b>3. 看观察断面。</b>三个编号是沿河设置的虚拟观察位置。卡片会给出当前浓度、首次达到阈值和峰值时刻；点击断面标题可在地图定位。模型参数和阈值均为教学假设。</p>'},
 records:{purpose:'查看模拟事件，或回到事件发生时的推演。',title:'事件记录怎么看',body:'<p><b>先选记录类型。</b>水位预警、照片巡检和污染推演放在同一列表，记录只保存在当前浏览器。</p><p><b>“已核查”是人工标记。</b>它只表示你看过这条记录，不会降低水位、停止污染或认定现场问题已解决；可以撤销。</p><p><b>回到当时的内容。</b>“查看地点”会返回地图，“查看推演”会恢复保存的河段、参数和模拟时刻。导出记录不会上传数据。</p>'},
 compare:{purpose:'选两个地点，比较它们距各自阈值的差值。',title:'地点对比说明',body:'<p>两个地点可能使用不同的水位基准，因此这里不直接比较绝对水位高低，而是比较“当前水位减去该地点教学阈值”。</p><p>曲线为0表示达到阈值，大于0表示超出，小于0表示尚未达到。选择框只改变对比对象，不修改地点读数。</p>'},
 table:{purpose:'集中查看读数，点击“定位”可返回地图。',title:'地点数据表说明',body:'<p>水域筛选决定表格中显示哪些地点。水位、流量和pH均为教学读数，状态由各地点自己的教学阈值判断。</p><p>点击地点名称或“定位”返回总览，并定位到该地点。导出读数会下载当前水域的数据。</p>'}
 };const h=helps[key]||helps.water;return `<section class="monitor-task-guide"><p>${h.purpose}</p><details class="monitor-howto" data-card-title="${h.title}"><summary>操作说明</summary>${h.body}</details></section>`}
function renderMonitorCompare(){if(state.compare===null||state.compare===state.selected)state.compare=(visibleStations().find(p=>p.index!==state.selected)||stations.find(p=>p.index!==state.selected)).index;return `<div class="monitor-subpage-heading"><div><h2>地点水位对比</h2><p>以各自阈值为0线，比较两个地点的水位变化。</p></div><a class="btn" href="#/monitor">返回水情总览</a></div><section class="monitor-compare-controls panel">${comparisonControls()}</section>${chartPanel({comparison:true})}`}
function renderMonitorTable(){return `<section class="monitor-table-page"><div class="monitor-subpage-heading"><div><h2>地点数据表</h2><p>查看当前水域的所有地点和模拟读数。</p></div><a class="btn" href="#/monitor">返回水情总览</a></div><section class="panel"><div class="monitor-table-filter"><label for="region-select"><span>水域</span>${regionSelect()}</label><button class="btn" id="export-csv">导出读数</button></div>${stationTable(true)}</section></section>`}

function renderMonitor(){return `<div class="monitor-console">${header('看水情','河湖读数与推演，均为教学模拟。')} ${monitorToolTabs()}${monitorHelpDetails(state.monitorSubpage||state.monitorTool)}<div id="monitor-tool-panel" role="tabpanel" aria-labelledby="monitor-tool-${state.monitorTool}">${({water:()=>state.monitorSubpage==='compare'?renderMonitorCompare():state.monitorSubpage==='table'?renderMonitorTable():renderMonitorOverview(),rain:renderMonitorRain,pollution:()=>window.HydroPollutionView.render(),records:renderMonitorRecords}[state.monitorTool]||renderMonitorOverview)()}</div></div>`}
function sandboxHTML(){const c=state.scenario,rainNow=c.active?Hydro.rainfall(c,c.minute):60,gateNow=c.active?Hydro.gateOpening(c,c.minute):0,scope=c.active?c.scope:(state.region==='all'?'qinhuai':state.region);return `<section class="sandbox-panel" aria-labelledby="sandbox-title"><div class="sandbox-heading"><h3 id="sandbox-title">雨强与闸门</h3><button class="btn" data-sandbox="reset">${icon('refresh')}重置</button></div><div class="rain-presets" role="group" aria-label="选择降雨场景">${[30,60,90,120].map(v=>`<button type="button" data-rain-preset="${v}" aria-pressed="${c.active?c.rain===v:v===60}" aria-label="雨强${v}毫米每小时"><span>${v}</span><span class="rain-preset-unit">mm/h</span></button>`).join('')}</div><div class="sandbox-live"><div class="sandbox-inputs"><div class="sandbox-controls"><label class="rain-control" for="sandbox-rain"><span>设置雨强 <output id="rain-output">${rainNow}</output> <small>mm/h</small></span><input id="sandbox-rain" type="range" min="0" max="120" step="10" value="${rainNow}" aria-label="演示降雨强度"><span class="range-ends"><span>无雨</span><span>强降雨</span></span></label><div class="playback-control"><div><button class="playback-button" id="sandbox-play" data-sandbox="play" aria-label="${c.playing?'暂停推演':'播放推演'}">${icon(c.playing?'pause':'play')}<span>${c.playing?'暂停':'播放推演'}</span></button><label for="sandbox-time">模拟第 <output id="time-output">${c.minute}</output><span> / 120 分钟</span></label><button class="sandbox-step" data-sandbox="step" aria-label="前进10分钟">前进10分</button></div><input id="sandbox-time" type="range" min="0" max="120" step="5" value="${c.minute}" aria-label="推演时间轴"></div></div><div class="scenario-weather"><span id="rain-phase">${scenarioPhase()}</span><button data-sandbox="stop-rain">现在停雨</button></div>${scope==='lake'?'<p class="lake-simulation-note">两座湖泊分别蓄水、缓慢回落。</p>':`<div class="virtual-gate gate-control"><label for="sandbox-gate">虚拟调节闸 <output id="gate-output">${gateNow}%</output></label><div class="gate-slider"><input type="range" id="sandbox-gate" min="0" max="100" step="1" value="${gateNow}" aria-label="虚拟调节闸开度" aria-valuetext="${gateNow}% 开度"><div class="gate-slider-rail" aria-hidden="true"><span class="gate-slider-fill" style="transform:scaleX(${gateNow/100})"></span><span class="gate-slider-thumb" style="left:${gateNow}%"></span></div></div><span>${stations[Hydro.network[scope].gate].name} · 仅教学调节</span></div>`}</div><div id="sandbox-result">${scenarioResultHTML()}</div></div><div class="sandbox-flow" id="sandbox-flow">${flowSequenceHTML(scope)}</div><p class="sandbox-insight" id="sandbox-insight" role="status">${sandboxInsight()}</p><details class="sandbox-advanced"><summary>推演规则</summary><p>教学模拟，非实测或预报。预设降雨持续40分钟，可随时停雨或修改雨强；水位渐进上涨，停雨后仍会延迟响应再回落。调闸逐步降低起点水位、增加后续来水，不连接现实设备。秦淮河为分支时滞示意，长江为先后响应，两座湖泊独立。</p><p>时间轴可回放。修改雨强或闸门仅改变当前时刻之后的该项操作；重选雨量场景会重新开始，历史台账保留。颜色为教学分级：距阈值0.4m以内临近、达到阈值超限、高出0.6m为高位。</p></details></section>`}
function scenarioPhase(){const c=state.scenario;if(!c.active)return '参数已就绪 · 点击“播放推演”开始';if(c.minute===0&&!c.playing)return `雨强 ${c.rain} mm/h · 尚未播放`;const rain=Hydro.rainfall(c,c.minute);if(c.minute>=120)return '本轮已结束 · 可拖动时间轴回看';if(!c.playing)return `已暂停在模拟第${c.minute}分钟 · 可继续播放`;return rain?`正在推演 · 第${c.minute}分钟 · 降雨 ${rain} mm/h`:'雨已停 · 观察水位的滞后回落'}
function scenarioResultHTML(){const c=state.scenario,s=stations[state.selected];if(!c.active)return `<div class="scenario-idle">${icon('wave')}<p>点击“播放推演”，这里会显示所选地点的水位变化。</p></div>`;if(s.group!==c.scope)return `<div class="scenario-idle"><p>当前推演：${groupNames[c.scope]}。${s.name}未参与本轮。</p><button class="source-link" data-record-station="${Hydro.network[c.scope].order[0]}">查看推演地点</button></div>`;
 const data=Array.from({length:61},(_,i)=>hydroModel.sample({...c,minute:i*2})[s.index]),unregulated=Array.from({length:61},(_,i)=>hydroModel.sample({...c,minute:i*2,gate:0,gateEvents:[]})[s.index]);
 const plotWidth=matchMedia('(max-width:760px)').matches?Math.max(220,Math.min(480,innerWidth-104)):480;const values=[...data,...unregulated].map(v=>v.level),min=Math.min(s.base-.15,...values)-.12,max=Math.max(s.limit+.15,...values)+.12,y=v=>144-(v-min)/(max-min)*120,x=t=>18+t/120*(plotWidth-36);
 const path=rows=>rows.filter((_,i)=>i*2<=c.minute).map((v,i)=>`${i?'L':'M'}${x(i*2).toFixed(1)},${y(v.level).toFixed(1)}`).join(' '),actual=path(data),reference=path(unregulated),point=`L${x(c.minute).toFixed(1)},${y(s.level).toFixed(1)}`,delta=s.level-s.base;
 const without=hydroModel.sample({...c,gate:0,gateEvents:[]})[s.index],effect=s.level-without.level,hasGate=c.gateEvents?.length?c.gateEvents.some(e=>e.value>0&&e.at<c.minute):c.gate>0&&c.gateAt<c.minute;
 return `<div class="scenario-result-heading"><div><h3>${s.name}</h3><span>${delta>=0?'较初始上涨':'较初始回落'} <strong>${fmt(Math.abs(delta))} m</strong></span></div><button class="source-link" data-view-station="${s.index}">地图定位 ${icon('pin')}</button></div><div class="scenario-plot"><svg viewBox="0 0 ${plotWidth} 190" role="img" aria-label="${s.name}教学水位过程，当前${fmt(s.level)}米"><path d="M18 144H${plotWidth-18}" stroke="#ccdcd4" fill="none"/><path d="M18 ${y(s.limit).toFixed(1)}H${plotWidth-18}" stroke="#bb8e64" stroke-dasharray="5 5" fill="none"/><text x="${plotWidth-18}" y="${(y(s.limit)-7).toFixed(1)}" text-anchor="end">教学阈值 ${s.limit} m</text><path d="${actual} ${point} L${x(c.minute).toFixed(1)},144 L18,144Z" fill="#4b949219"/>${hasGate?`<path d="${reference}" stroke="#999e94" stroke-width="2" stroke-dasharray="5 5" fill="none"/>`:''}<path d="${actual} ${point}" stroke="${stageInfo(s).color}" stroke-width="3" fill="none" stroke-linejoin="round"/><circle cx="${x(c.minute).toFixed(1)}" cy="${y(s.level).toFixed(1)}" r="5" fill="${stageInfo(s).color}"/><text x="18" y="177">0分</text><text x="${plotWidth/2}" y="177" text-anchor="middle">60分</text><text x="${plotWidth-18}" y="177" text-anchor="end">120分</text></svg></div><div class="scenario-result-bottom"><strong>${fmt(s.level)} <small>m · 模拟水位</small></strong>${hasGate?`<span class="gate-effect">比未调节${effect<=0?'低':'高'} ${fmt(Math.abs(effect))} m</span><span class="plot-reference">虚线：未调节</span>`:stageBadge(s)}</div>`}
function flowSequenceHTML(scope){const stop=index=>{const s=stations[index],delta=s.level-hydroModel.baseline()[index].base;return `<button data-station="${index}" class="flow-stop ${stageInfo(s).key} ${state.selected===index?'selected':''}"><span>${s.name}</span><strong>${delta>=0?'+':''}${fmt(delta)} m</strong></button>`};if(scope==='qinhuai')return `<div class="flow-branch-root">${stop(2)}</div><span class="flow-branch-arrow" aria-hidden="true"><svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#flow-branch"></use></svg></span><div class="flow-branch-outlets">${stop(1)}${stop(0)}</div><span class="flow-topology-note">两支出口 · 教学时滞示意</span>`;return Hydro.network[scope].order.map((index,i)=>`${i?`<span class="flow-connector" aria-hidden="true">${scope==='lake'?'·':'<svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-right"></use></svg>'}</span>`:''}${stop(index)}`).join('')}

function sandboxInsight(){const c=state.scenario;if(!c.active)return '预设雨强持续40分钟；可调整雨强、停雨时间与闸门开度。';const group=Hydro.network[c.scope],next=group.order.find(i=>(group.lag[i]||0)>c.minute);if(c.minute>=120)return '推演结束。时间轴可回看120分钟内的水位变化。';if(c.gateEvents?.some(e=>e.value>0&&e.at<=c.minute))return '调节效果逐渐传递：起点水位降低，后续地点可能承接更多来水。灰色虚线为同场降雨下未调节的对照。';if(next!==undefined)return `${stations[next].name}约在${group.lag[next]}分钟开始响应；停雨后，后续地点仍可能继续上涨。`;return Hydro.rainfall(c,c.minute)?'各地点已开始响应。可调节虚拟闸门，对比同一场雨下的变化。':'雨已停，来水仍在传递；湖泊与河道会按各自节奏回落。'}
function comparisonControls(){return `<div class="comparison-controls"><label for="compare-primary-station"><span>地点一</span><select id="compare-primary-station">${stations.map(p=>`<option value="${p.index}" ${p.index===state.selected?'selected':''}>${p.name}</option>`).join('')}</select></label><label for="compare-station"><span>地点二</span><select id="compare-station">${stations.filter(p=>p.index!==state.selected).map(p=>`<option value="${p.index}" ${p.index===state.compare?'selected':''}>${p.name}</option>`).join('')}</select></label><span>比较的是距各自教学阈值的差值：0表示达到阈值，负值表示尚未达到。</span></div>`}
function tableRows(full=false){return (full?visibleStations():visibleStations().slice(0,4)).map(s=>`<tr class="${s.index===state.selected?'selected':''}" data-table-station="${s.index}"><td><button class="table-station-button" data-station="${s.index}" aria-pressed="${s.index===state.selected}">${s.name}</button></td><td>${fmt(s.level)} m</td><td>${full?fmt(s.flow,0)+' m³/s · pH '+fmt(s.ph,1):fmt(s.limit)+' m'}</td><td>${stageBadge(s)}</td><td><button class="table-link" data-view-station="${s.index}">定位</button></td></tr>`).join('')}
function syncNotification(){const count=hydroLedger.pendingCount(),button=document.querySelector?.('#notification-button');if(!button)return count;button.classList.toggle('has-pending',count>0);button.dataset.pendingCount=String(count);button.setAttribute('aria-label',count?`查看预警通知，${count}条待处理记录`:'查看预警通知，暂无待处理记录');button.title=count?`${count}条待处理记录`:'暂无待处理记录';return count}
function refreshLedgerViews(recordId){syncNotification();const summary=$('.monitor-record-summary');if(summary)summary.textContent=getMonitorRecords().length+'条记录 · '+hydroLedger.pendingCount()+'条待核查';const body=$('#monitor-ledger-body');if(body){body.innerHTML=ledgerHTML(state.monitorRecordFilter);body.dataset.snapshot=JSON.stringify(getMonitorRecords())}const modal=$('#dialog');if(modal?.open)openAlertLog();if(recordId){const scope=modal?.open?$('#dialog-content'):body;$(`[data-record-handle="${recordId}"]`,scope||document)?.focus({preventScroll:true})}}
function getMonitorRecords(){const pollution=(window.HydroPollutionView?.records?.()||[]).map(e=>({...e,id:'pollution:'+e.id,pollutionId:e.id,type:'pollution',status:'noted',severity:e.kind==='enter'?2:0,title:`${e.reachName} · 断面${e.point+1} · ${e.kind==='enter'?'模拟超阈':'模拟回落'}`,summary:`推演第${Math.round(e.minute)}分钟，${e.kind==='enter'?'达到':'降回'}教学比较阈值 ${e.threshold} mg/L。`}));return [...hydroLedger.list(),...pollution].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at))}
function ledgerHTML(filter='all'){const all=getMonitorRecords(),list=all.filter(r=>filter==='all'||r.type===filter);return `<div class="ledger-tools"><span>${hydroLedger.available()?'记录保存在此浏览器':'本机存储不可用，记录仅保留本次会话'}</span><div class="ledger-tool-actions">${filter!=='pollution'&&hydroLedger.pendingCount()?`<button class="btn" data-record-handle-all>全部标记已核查</button>`:''}${filter==='pollution'&&list.length?`<button class="btn" data-clear-pollution-records>清空污染记录</button>`:''}<button class="btn" data-ledger-export>导出全部记录</button></div></div>${list.length?`<div class="ledger-list">${list.map(r=>`<article class="ledger-entry"><span class="ledger-symbol ${Hydro.stages[r.severity]?.key||'watch'}">${icon(r.type==='inspection'?'scan':r.type==='pollution'?'drop':'wave')}</span><div class="ledger-copy"><span class="monitor-record-type">${({water:'水位预警',inspection:'照片巡检',pollution:'污染推演'})[r.type]}</span><h3>${escapeHTML(r.title)}</h3><p>${r.type==='pollution'?'虚拟断面':escapeHTML(stations[r.station].name)} · ${new Date(r.at).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})}</p>${r.summary?`<details><summary>查看内容</summary><p>${escapeHTML(r.summary)}</p>${(r.observations||[]).map(o=>`<p><b>${escapeHTML(o.name)}</b>：${escapeHTML(o.explanation)}</p>`).join('')}</details>`:''}</div><span class="ledger-status ${r.type==='pollution'?(r.kind==='enter'?'pending':'ended'):r.status}">${r.type==='pollution'?(r.kind==='enter'?'模拟超阈':'已回落'):({pending:'待核查',handled:'已核查',ended:'场景已恢复',noted:'观察已记录'})[r.status]}</span><div class="ledger-entry-actions">${r.type==='pollution'?`<button data-open-pollution-record="${escapeHTML(r.pollutionId)}">查看推演</button>`:`<button data-record-station="${r.station}">查看地点</button>${r.status==='ended'||r.status==='noted'?'':`<button data-record-handle="${r.id}">${r.status==='handled'?'撤销核查标记':'标记已核查'}</button>`}`}</div></article>`).join('')}</div>`:'<div class="ledger-empty">当前分类暂无记录。水位预警、巡检观察与污染推演事件会保存在这里。</div>'}`}
function inspectionContextHTML(){return state.aiStation===null?'':`<div class="inspection-context"><span>${icon('pin')}演示关联：${stations[state.aiStation].name}</span><button data-record-station="${state.aiStation}">返回水情 <svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-right"></use></svg></button></div>`}
function inspectionSaveHTML(){return `<details class="inspection-save"><summary>记入巡检台账</summary><label for="inspection-station">演示关联地点</label><select id="inspection-station"><option value="">请选择地点</option>${stations.map(s=>`<option value="${s.index}" ${state.aiStation===s.index?'selected':''}>${s.name}</option>`).join('')}</select><label class="review-check"><input id="inspection-review" type="checkbox" ${state.aiNeedsReview?'checked':''}>需要人工核查</label><p>仅保存分析文字，示例图片并非该地点的实拍。</p><button class="btn primary" data-save-inspection ${state.aiSaved?'disabled':''}>${state.aiSaved?'已保存至本机台账':'保存巡检记录'}</button></details>`}
function saveInspection(){if(!state.aiDone||state.aiRejected||state.aiSaved)return;if(!Number.isInteger(state.aiStation)){aiFeedback('请选择一个演示关联地点。');return}const needsReview=!!state.aiNeedsReview;hydroLedger.add({type:'inspection',station:state.aiStation,status:needsReview?'pending':'noted',severity:needsReview?1:0,needsReview,title:`${stations[state.aiStation].name} · ${needsReview?'AI观察待核查':'AI巡检记录'}`,summary:state.aiSummary.slice(0,600),observations:state.results.map(r=>({name:r.name.slice(0,50),explanation:r.explanation.slice(0,400)})),scene:aiIsSample()?'内置历史照片 · 演示关联':'用户选择图片 · 演示关联'});state.aiSaved=true;render();toast(needsReview?'已记入待核查台账，未认定为现场险情。':'巡检观察已保存在此浏览器。')}
function syncScenarioEvents(){const run=state.scenario.active?state.scenario.run:'baseline';for(const s of stations)if(!state.scenario.active||s.group===state.scenario.scope&&(Math.abs(s.level-hydroModel.baseline()[s.index].base)>.08||!isWarn(s)))hydroLedger.water(s,run);state.alerts=hydroLedger.list().map(r=>({...r,time:new Date(r.at),kind:r.type==='inspection'?'info':'warn'}));syncNotification()}
function applyScenario(){const sample=hydroModel.sample(state.scenario);for(let i=0;i<stations.length;i++)Object.assign(stations[i],{level:sample[i].level,flow:sample[i].flow,ph:hydroModel.baseline()[i].ph});syncScenarioEvents();updateReadings()}
function ensureScenario(){if(!state.scenario.active){state.paused=false;state.scenario={...state.scenario,active:true,scope:state.region==='all'?'qinhuai':state.region,run:`scenario-${Date.now()}`};state.storm=true}}
function resetSandbox(notify=true){if(state.scenario.active)hydroLedger.endRun(state.scenario.run);state.scenario={active:false,rain:0,minute:0,scope:state.region==='all'?'qinhuai':state.region,gate:0,gateAt:0,rainEvents:[],gateEvents:[],playing:false,run:''};state.storm=false;state.paused=false;state.tick=0;for(let i=0;i<stations.length;i++){Object.assign(stations[i],hydroModel.baseline()[i]);histories[i]=baselineHistories[i].map(h=>({...h}))}if(notify){syncScenarioEvents();render();toast('已恢复所有地点初始读数，历史台账保留。')}}
let scenarioResizeTimer;
function startRainScenario(rain=90){if(state.scenario.active)resetSandbox(false);ensureScenario();state.selected=Hydro.network[state.scenario.scope].order[0];state.scenario.rain=rain;state.scenario.rainEvents=Hydro.changes([],0,rain,40);state.scenario.minute=15;state.scenario.playing=true;applyScenario();render()}
function simulateStorm(){if(state.scenario.active){resetSandbox();return}startRainScenario(90);toast('降雨推演已开始，40分钟后自动停雨。')}
function updateSandboxUI(){const c=state.scenario;for(const [id,value] of [['rain-output',c.active?Hydro.rainfall(c,c.minute):60],['time-output',c.minute],['gate-output',Hydro.gateOpening(c,c.minute)+'%']]){const el=$('#'+id);if(el)el.textContent=value}const input=$('#sandbox-time');if(input)input.value=c.minute;const rainInput=$('#sandbox-rain');if(rainInput)rainInput.value=c.active?Hydro.rainfall(c,c.minute):60;const gateInput=$('#sandbox-gate');if(gateInput){const opening=Hydro.gateOpening(c,c.minute);gateInput.value=opening;gateInput.setAttribute('aria-valuetext',opening+'% 开度');const fill=$('.gate-slider-fill'),thumb=$('.gate-slider-thumb');if(fill)fill.style.transform='scaleX('+opening/100+')';if(thumb)thumb.style.left=opening+'%'}const play=$('#sandbox-play');if(play){play.innerHTML=icon(c.playing?'pause':'play')+'<span>'+(c.playing?'暂停':'播放推演')+'</span>';play.setAttribute('aria-label',c.playing?'暂停推演':'播放推演')}const phase=$('#rain-phase');if(phase)phase.textContent=scenarioPhase();const stop=$('[data-sandbox="stop-rain"]');if(stop)stop.disabled=!c.active||!Hydro.rainfall(c,c.minute)||c.minute>=120;$$('[data-rain-preset]').forEach(b=>b.setAttribute('aria-pressed',String(c.active?+b.dataset.rainPreset===c.rain:+b.dataset.rainPreset===60)));const result=$('#sandbox-result');if(result)result.innerHTML=scenarioResultHTML();const flow=$('#sandbox-flow');if(flow){const focused=flow.contains(document.activeElement)?document.activeElement.dataset.station:null;flow.innerHTML=flowSequenceHTML(c.active?c.scope:state.region==='all'?'qinhuai':state.region);if(focused!==null)$(`[data-station="${focused}"]`,flow)?.focus({preventScroll:true})}const insight=$('#sandbox-insight');if(insight)insight.textContent=sandboxInsight();document.body.classList.toggle('simulation-running',c.active&&c.playing&&!state.paused)}

function setMonitorTool(tool){state.scenario.playing=false;state.monitorSubpage='';state.compare=null;state.monitorTool=monitorTools.some(([key])=>key===tool)?tool:'water';history.replaceState(null,'','#/monitor'+(state.monitorTool==='water'?'':'?tool='+state.monitorTool));render();$('#monitor-tool-'+state.monitorTool)?.focus({preventScroll:true})}
function ensureRainSetup(){if(!state.scenario.active){ensureScenario();state.scenario.rain=60;state.scenario.rainEvents=Hydro.changes([],0,60,40)}const scope=state.scenario.scope;if(stations[state.selected].group!==scope)state.selected=Hydro.network[scope].order[0]}
function configureRain(rain){if(state.scenario.active)resetSandbox(false);ensureScenario();state.scenario.rain=rain;state.scenario.rainEvents=Hydro.changes([],0,rain,40);state.scenario.minute=0;state.scenario.playing=false;state.selected=Hydro.network[state.scenario.scope].order[0];applyScenario();render()}

function handleWorkbenchClick(e){const t=e.target.closest('[data-monitor-record-filter],[data-open-pollution-record],[data-clear-pollution-records],[data-monitor-tool],[data-map-alert],[data-map-details],[data-monitor-view],[data-rain-preset],[data-sandbox],[data-inspect],[data-record-station],[data-record-handle-all],[data-record-handle],[data-ledger-export],[data-save-inspection]');if(!t)return false;
 if(t.hasAttribute('data-monitor-tool')){setMonitorTool(t.dataset.monitorTool);return true}
 if(t.hasAttribute('data-monitor-record-filter')){state.monitorRecordFilter=['water','inspection','pollution'].includes(t.dataset.monitorRecordFilter)?t.dataset.monitorRecordFilter:'all';render();$('[data-monitor-record-filter="'+state.monitorRecordFilter+'"]')?.focus({preventScroll:true});return true}
 if(t.hasAttribute('data-open-pollution-record')){if(window.HydroPollutionView?.inspectRecord(t.dataset.openPollutionRecord)){$('#dialog')?.close();setMonitorTool('pollution');}return true}
 if(t.hasAttribute('data-clear-pollution-records')){window.HydroPollutionView?.clearRecords();render();return true}
 if(t.hasAttribute('data-map-alert')){const index=+t.dataset.mapAlert;selectStation(index,false,true);$('#river-map')?.scrollIntoView({block:'start',behavior:'instant'});geographicController?.focusStation(index,{openPopup:true,keyboard:navigationByKeyboard});return true}
 if(t.hasAttribute('data-map-details')){selectStation(+t.dataset.mapDetails,true,true);return true}
 if(t.hasAttribute('data-rain-preset')){configureRain(+t.dataset.rainPreset);return true}
 if(t.hasAttribute('data-monitor-view')){state.monitorView=t.dataset.monitorView==='ops'?'ops':'public';render()}
 if(t.hasAttribute('data-sandbox')){const action=t.dataset.sandbox;if(action==='reset'){resetSandbox();return true}if(action==='storm'){startRainScenario(90);$('#sandbox-title')?.scrollIntoView({block:'start',behavior:'instant'});return true}ensureRainSetup();if(action==='stop-rain'){state.scenario.rain=0;state.scenario.rainEvents=Hydro.changes(state.scenario.rainEvents,state.scenario.minute,0);state.scenario.playing=true}else if(action==='step'){state.scenario.minute=Math.min(120,state.scenario.minute+10);state.scenario.playing=false}else{if(state.scenario.minute===120){state.scenario.minute=0}state.scenario.playing=!state.scenario.playing}state.paused=false;applyScenario();updateSandboxUI()}
 if(t.hasAttribute('data-inspect')){state.aiStation=+t.dataset.inspect;state.aiSaved=false;location.hash='/ai?station='+stations[state.aiStation].id}
 if(t.hasAttribute('data-record-station')){const index=+t.dataset.recordStation;if(!stations[index])return true;$('#dialog')?.close();state.selected=index;state.region=stations[index].group;state.monitorTool='water';const hash='#/monitor?station='+stations[index].id;if(location.hash===hash)render();else location.hash=hash}
 if(t.hasAttribute('data-record-handle-all')){const count=hydroLedger.handlePending();refreshLedgerViews();if($('#dialog')?.open)$('#dialog-close')?.focus({preventScroll:true});toast(`已将 ${count} 条记录标记为已核查，可在记录中撤销。`);return true}
 if(t.hasAttribute('data-record-handle')){hydroLedger.handle(t.dataset.recordHandle);refreshLedgerViews(t.dataset.recordHandle);toast('已更新演示处置状态，水位仍按读数判断。')}
 if(t.hasAttribute('data-ledger-export')){download(JSON.stringify({title:'智水监测 · 本机教学台账',exportedAt:new Date().toISOString(),boundary:'水位与污染均为教学模拟，AI为模型观察与人工关联；不是现场险情认定。不含图片。',records:getMonitorRecords()},null,2),'智水-教学台账.json','application/json;charset=utf-8')}
 if(t.hasAttribute('data-save-inspection'))saveInspection();return true;
}
function bindWorkbench(){
 $('#compare-primary-station')?.addEventListener('change',e=>{const index=+e.target.value;state.region=stations[index].group;selectStation(index)});
 $('#station-select')?.addEventListener('change',e=>selectStation(+e.target.value));
 $('.monitor-tool-tabs')?.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const index=monitorTools.findIndex(([key])=>key===state.monitorTool),key=monitorTools[e.key==='Home'?0:e.key==='End'?monitorTools.length-1:(index+(e.key==='ArrowRight'?1:-1)+monitorTools.length)%monitorTools.length][0];$('[data-monitor-tool="'+key+'"]')?.click()});
 $('#sandbox-rain')?.addEventListener('input',e=>{ensureRainSetup();state.scenario.rain=+e.target.value;state.scenario.rainEvents=Hydro.changes(state.scenario.rainEvents,state.scenario.minute,state.scenario.rain,40);state.scenario.playing=false;applyScenario();updateSandboxUI()});
 $('#sandbox-time')?.addEventListener('input',e=>{ensureRainSetup();state.scenario.minute=+e.target.value;state.scenario.playing=false;applyScenario();updateSandboxUI()});
 $('#sandbox-gate')?.addEventListener('input',e=>{ensureRainSetup();state.scenario.gate=+e.target.value;state.scenario.gateAt=state.scenario.minute;state.scenario.gateEvents=Hydro.changes(state.scenario.gateEvents,state.scenario.minute,state.scenario.gate);state.scenario.playing=false;applyScenario();updateSandboxUI()});
 $('#compare-station')?.addEventListener('change',e=>{state.compare=e.target.value===''?null:+e.target.value;if(state.compare!==null)state.metric='level';state.chart?.destroy();makeChart()});
 $$('[data-hydro-layer]').forEach(el=>el.addEventListener('change',()=>{state.layers[el.dataset.hydroLayer]=el.checked;geographicController?.setLayers(state.layers)}));
 $('#inspection-station')?.addEventListener('change',e=>{state.aiStation=e.target.value===''?null:+e.target.value;state.aiSaved=false;const save=$('[data-save-inspection]');if(save){save.disabled=false;save.textContent='保存巡检记录'}});
 $('#inspection-review')?.addEventListener('change',e=>{state.aiNeedsReview=e.target.checked;state.aiSaved=false;const save=$('[data-save-inspection]');if(save){save.disabled=false;save.textContent='保存巡检记录'}});updateSandboxUI();
}
function openAlertLog(){openDialog(`<div class="dialog-eyebrow">水情 · 巡检 · 污染推演</div><h2>事件记录</h2>${ledgerHTML()}<div class="dialog-actions"><button class="btn primary" data-close-dialog>关闭</button></div>`)}

function renderHome(){return `<section class="cinematic-hero" aria-labelledby="hero-title"><div class="cinematic-copy"><h1 id="hero-title"><span class="hero-title-line">南京河湖</span><span class="hero-title-line luminous-title">水情与观察</span></h1><div class="cinematic-actions"><a class="btn primary hero-primary" href="#/monitor"><span>看水情</span>${icon('arrow')}</a><a class="hero-secondary" href="#/experience"><span class="play-orbit">${icon('wave')}</span><span>水文体验</span></a></div></div><div class="hero-scene" aria-hidden="true"><div class="terrain-fallback">${riverArt()}</div><canvas id="digital-river"></canvas><div class="scene-coordinate"><b>数字江河 · 概念可视化</b></div></div><div class="hero-bottom"><a class="scroll-cue" href="#/home?section=home-discovery"><span>南京实景与水利知识 <svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-down"></use></svg></span></a><div class="hero-bottom-right"><span class="simulation-label">地形为概念视觉 · 读数为教学模拟</span></div></div></section>${homeDiscovery()}${homeEntries()}`}
function homeEntries(){return `<section class="home-entries" id="start"><div><h2>水情与河湖</h2></div><div class="home-task-grid"><a class="task-monitor" href="#/monitor"><span class="task-symbol" aria-hidden="true">${icon('pin')}</span><h3>水情监测</h3><strong>查看水情 <svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-right"></use></svg></strong></a><a class="task-ai" href="#/ai"><span class="task-symbol" aria-hidden="true">${icon('scan')}</span><h3>水域识别</h3><strong>识别图片 <svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-right"></use></svg></strong></a><a class="task-experience" href="#/experience"><span class="task-symbol" aria-hidden="true">${icon('wave')}</span><h3>水文体验</h3><strong>打开实验 <svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-right"></use></svg></strong></a></div></section>`}

