const aiImage=()=>state.image||aiScenes[state.aiScene].file;
const aiIsSample=()=>!state.image||state.sample;
const visibleAIResults=()=>state.results.map((r,index)=>({...r,index}));
function renderAI(){const sample=aiIsSample(),scene=aiScenes[state.aiScene];return `${header('AI 水域识别','')}
${inspectionContextHTML()}<div class="ai-layout vision-workbench real-vision">
 <section class="panel vision-canvas-panel" aria-labelledby="vision-stage-title">
  <div class="vision-panel-heading"><h2 id="vision-stage-title">${sample?scene.title:'已选图片'}</h2><button class="btn primary" id="detect-button" ${state.detecting?'disabled':''}>${icon('scan')}${state.detecting?'正在识别…':state.aiDone?'重新识别':'开始识别'}</button></div>
  <div class="vision-viewbar" ${state.aiDone?'':'hidden'}><div class="vision-view-switch" role="group" aria-label="画面对照"><button data-ai-view="annotated" aria-pressed="${state.aiView==='annotated'}">标注视图</button><button data-ai-view="original" aria-pressed="${state.aiView==='original'}">查看原图</button></div></div>
  <div class="detection-stage vision-stage" id="detection-stage" aria-label="可拖入图片的识别画面">${stageHTML()}</div>
  <div class="vision-image-meta">${sample?`<details class="image-credit"><summary>图片信息</summary><div class="image-credit-body"><p><a href="${scene.source}" target="_blank" rel="noopener">${escapeHTML(decodeURIComponent(scene.source.split('/wiki/File:')[1]||scene.title).replace(/_/g,' '))}</a></p><p>摄影：${escapeHTML(scene.credit)}${state.aiScene==='ecology'?' · <a href="https://delso.photo" target="_blank" rel="noopener">delso.photo</a>':''} · <a href="${scene.licenseUrl}" target="_blank" rel="noopener">${scene.license}</a></p><p>原图内容未修改；页面缩放，识别标注为可关闭的叠加图层。</p></div></details>`:`<span>${escapeHTML(state.aiFile?.name||'已载入图片')}</span>`}${state.aiDone?'<button id="ai-show-results">查看结果 <svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-down"></use></svg></button>':''}</div>
  <div class="vision-pick-row"><input class="file-input" id="image-upload" type="file" accept="image/jpeg,image/png,image/webp" aria-label="上传图片"><label for="image-upload" class="btn upload-label">${icon('upload')}上传图片</label></div>
  <div class="vision-samples-heading"><h3>选择例图</h3></div><div class="vision-samples" role="group" aria-label="选择实拍例图">${Object.entries(aiScenes).map(([id,scene])=>`<button class="vision-sample ${sample&&state.aiScene===id?'active':''}" data-ai-scene="${id}" aria-pressed="${sample&&state.aiScene===id}"><img src="${scene.file}" alt="" width="90" height="60"><span><strong>${scene.title}</strong></span><span class="vision-sample-check" aria-hidden="true">${sample&&state.aiScene===id?'✓':'<svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-up-right"></use></svg>'}</span></button>`).join('')}</div>
  <p class="vision-consent">开始识别后发送图片分析，本站不保存图片。</p>
  <span id="ai-feedback" hidden></span>
 </section>
 <aside class="panel vision-results-panel" aria-labelledby="vision-results-title">
  <div class="vision-panel-heading"><h2 id="vision-results-title" tabindex="-1">识别结果</h2>${state.aiDone?`<span class="badge green" id="result-count">${state.results.length} 项结果</span>`:''}</div>
  <div id="vision-run-status" role="status" aria-live="polite">${aiStatusHTML()}</div>
  <div id="detection-results">${resultsHTML()}</div>
  
  ${state.aiDone?`<div class="vision-result-footer"><button class="btn" id="ai-export">${icon('download')}导出分析记录</button></div>${inspectionSaveHTML()}`:''}
 </aside>
</div>
<section class="ai-bottom vision-reading"><details><summary>使用说明</summary><div class="vision-help-copy"><p>选择图片时只在浏览器预览；点击开始后，浏览器会缩小图片、去除附带元数据，并发送到云端进行分析。本站不保存图片文件，云端服务会按其规则处理请求，请勿上传敏感图片。</p><p>结果来自 AI 对画面的分析，不是专业检测报告。框选位置是估计，无法仅凭照片判断水质、饮用安全、物种或工程安全。取消会停止本页等待，已发送的分析可能仍继续。</p><p>导出为 JSON，不包含图片。图片识别设有次数限制。</p></div></details></section>`}
function stageHTML(){return `<img src="${aiImage()}" alt="${aiIsSample()?aiScenes[state.aiScene].title+'实拍照片':'用户选择的图片'}" id="preview-image"><div class="detection-overlay vision-overlay" id="detection-overlay" ${state.aiView==='original'?'hidden':''}>${boxesHTML()}</div>${state.detecting?'<div class="vision-scan" aria-hidden="true"></div><div class="vision-scanning-tag">AI 正在分析图片…</div>':''}`}
function boxesHTML(){return visibleAIResults().filter(r=>r.box).map(r=>`<button class="detect-box vision-box ${state.aiSelection===r.index?'selected':''}" data-ai-target="${r.index}" aria-pressed="${state.aiSelection===r.index}" aria-label="观察 ${r.index+1}：${escapeHTML(r.name)}，位置由AI估计" style="left:${r.box[0]}%;top:${r.box[1]}%;width:${r.box[2]}%;height:${r.box[3]}%"><span>${r.index+1} · ${escapeHTML(r.name)}</span><i aria-hidden="true"></i></button>`).join('')}
function aiStatusHTML(){return state.detecting?`<div class="vision-run-status working"><span class="vision-run-dot"></span><strong>${state.aiPhase===1?'准备图片…':'正在识别水域…'}</strong><button id="ai-cancel">取消</button></div>`:''}
function resultsHTML(){
 if(state.aiRejected)return `<div class="vision-scene-prompt" role="status">${icon('wave')}<h3>请更换水域照片</h3><p>${escapeHTML(state.aiRejected)}</p><button class="btn primary" data-ai-scene="ecology">使用水下示例 ${icon('arrow')}</button></div>`;
 if(!state.aiDone)return `<div class="vision-results-empty ${state.aiNotice?'vision-error':''}" ${state.aiNotice?'role="status"':''}>${icon(state.aiNotice?'warning':state.detecting?'scan':'wave')}<p>${escapeHTML(state.aiNotice|| (state.detecting?'正在分析图片…':'暂无识别结果'))}</p></div>`;
 return `<p class="vision-summary">${escapeHTML(state.aiSummary)}</p><div class="vision-result-list">${visibleAIResults().map(r=>`<${r.box?'button type="button"':'article'} class="vision-result-card ${r.box&&state.aiSelection===r.index?'selected':''}" ${r.box?`data-ai-target="${r.index}" aria-pressed="${state.aiSelection===r.index}" aria-label="在图中查看：${escapeHTML(r.name)}"`:''}><span class="vision-result-index">${r.index+1}</span><span class="vision-result-copy"><strong>${escapeHTML(r.name)}</strong><span>${escapeHTML(r.explanation)}</span></span></${r.box?'button':'article'}>`).join('')}</div>`}
function feature(type,title,copy){return `<article class="feature-card">${icon(type)}<h3>${title}</h3><p>${copy}</p></article>`}

const articles=[
{id:'flood',category:'水灾害',title:'水位与流量',desc:'水位表示水面的高程，流量表示单位时间通过断面的水量。',icon:'wave',time:'3 分钟',body:['水位是水面相对某个基准面的高程；流量是单位时间通过某个过水断面的水体体积。它们描述的是不同的物理量。','在一定条件下，水位与流量存在对应关系，但河床变化、回水等因素都会影响这种关系。因此，判断汛情需要结合降雨、水位、流量与工程运行信息。','本平台的水位曲线与阈值均为交互演示预设，不能据此判断真实河流的防汛形势。'],tip:'在水情页切换“水位”和“流量”，可查看对应单位和曲线。'},
{id:'reservoir',category:'水灾害',title:'水库的调蓄作用',desc:'预留库容、拦蓄洪水，以及防洪与供水之间的安排。',icon:'layers',time:'3 分钟',body:['水库可以在一定范围内调节来水与下泄水量。防洪调度的一个重要思路，是利用预留空间拦蓄一部分洪水，减轻下游的防洪压力。','蓄水需要统筹防洪、供水、生态等目标，实际调度取决于工程条件、预报结果和批准的调度方案。','因此，“水库越满越好”并不适用于所有时段。认识水库，需要同时看水位、库容、入库与出库流量。'],tip:'判断水库运行状态，还需参考库容和入出库流量。'},
{id:'quality',category:'水生态',title:'pH 与水质判断',desc:'pH 反映酸碱性，水质评价还需要结合其他检测指标。',icon:'quality',time:'2 分钟',body:['透明度与颜色可以反映某些水体特征，但清澈并不等于安全。水质评价需要依据用途与标准，结合多个检测指标进行。','pH 描述水的酸碱性；溶解氧反映溶于水中的氧含量。温度、污染物、营养盐等信息同样有助于理解水体状态。','本作品仅模拟展示 pH，不以单一 pH 数值推断水质类别、饮用安全或生态健康。'],tip:'在本平台中，“正常”只描述水位是否超过演示阈值，不代表真实水质评价。'},
{id:'saving',category:'水资源',title:'日常节约用水',desc:'修复漏水、按需取水和使用节水器具。',icon:'drop',time:'2 分钟',body:['水资源在时间和空间上的分布并不均匀。节约用水不仅是减少账单，也是在减少取水、供水与污水处理过程中的资源消耗。','及时修复漏水、按需取水、采用适宜的节水器具，都是可以从日常开始的行动。','重复利用水要注意用途与卫生条件。作品倡导按需用水，不提供饮用水处理方案。'],tip:'记录日常用水量，有助于发现漏水和不必要的消耗。'},
{id:'digital',category:'数字水利',title:'数字孪生水利',desc:'传感数据、模型分析与地图展示在水利管理中的用途。',icon:'cpu',time:'4 分钟',body:['数字孪生水利通过数字化表达、模拟分析与信息交互，辅助认识和管理现实中的水利对象。','传感观测提供数据基础，模型与分析帮助理解变化，可视化界面则把复杂信息呈现给使用者。实际系统需要长期的数据治理与专业验证。','本作品展示了其中“数据呈现与交互”的一环：模拟传感数据、联动站点与曲线、呈现预警。它没有接入真实数字孪生平台。'],tip:'本作品使用模拟读数，未接入实际数字孪生平台。'},
{id:'underwater',category:'数字水利',title:'水下图像识别',desc:'目标类别、位置标注，以及识别结果的局限。',icon:'scan',time:'3 分钟',body:['目标检测通常会给出物体类别、位置与模型置信度。边界框用于表达检测到的目标范围。','置信度是模型对结果的评分，不等同于经过验证的真实正确率。浑浊、遮挡和光照不足会降低水下图像的识别可靠性。','本作品接入真实图像分析。AI会根据图片生成观察和估计位置，可能出错，不能代替专业检测。'],tip:'在图片识别页可上传照片，并对照原图查看标注。'}
];
function filteredKnowledge(){return articles.filter(a=>(state.category==='全部内容'||a.category===state.category)&&(a.title+a.desc+a.body.join('')).toLowerCase().includes(state.search.trim().toLowerCase()))}
function knowledgeCount(){return state.search.trim()||state.category!=='全部内容'?`找到 ${filteredKnowledge().length} 篇`:`${articles.length} 篇基础知识`}
function renderKnowledge(){return `<section class="knowledge-index" aria-labelledby="knowledge-title"><header class="knowledge-heading"><div><h1 id="knowledge-title">水利知识</h1><p>水位、调蓄、水质与日常用水。</p></div><label class="search-box">${icon('search')}<input type="search" id="knowledge-search" placeholder="搜索知识" aria-label="搜索水利知识" value="${escapeHTML(state.search)}"></label></header><div class="knowledge-browse"><div class="filter-tabs" id="knowledge-tabs" role="group" aria-label="知识分类">${['全部内容','水灾害','水资源','水生态','数字水利'].map(c=>`<button type="button" data-category="${c}" class="${c===state.category?'active':''}" aria-pressed="${c===state.category}">${c==='全部内容'?'全部':c}</button>`).join('')}</div><p id="knowledge-count" role="status" aria-live="polite">${knowledgeCount()}</p></div><div class="knowledge-grid" id="knowledge-grid">${knowledgeCards()}</div><p class="knowledge-source">延伸阅读：<a href="https://www.mwr.gov.cn/" target="_blank" rel="noopener">水利部官方网站 <svg class="inline-arrow" aria-hidden="true" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-up-right"></use></svg></a></p></section>`}
function knowledgeCards(){const list=filteredKnowledge();return list.length?list.map(a=>`<article class="knowledge-card"><button type="button" class="knowledge-open" data-article="${a.id}" aria-haspopup="dialog" aria-labelledby="knowledge-title-${a.id}" aria-describedby="knowledge-desc-${a.id}"><span class="knowledge-symbol knowledge-symbol-${a.category==='水生态'?'green':a.category==='水资源'?'gold':'teal'}" aria-hidden="true">${icon(a.icon)}</span><span class="knowledge-copy"><span class="knowledge-meta">${a.category}<span aria-hidden="true">·</span>${a.time}</span><strong class="knowledge-title" id="knowledge-title-${a.id}">${a.title}</strong><span class="knowledge-description" id="knowledge-desc-${a.id}">${a.desc}</span></span><span class="knowledge-open-icon" aria-hidden="true">${icon('arrow')}</span></button></article>`).join(''):`<div class="no-results"><p>没有找到相关内容</p><button type="button" class="btn" data-reset-knowledge>查看全部知识</button></div>`}
function refreshKnowledge(){const grid=$('#knowledge-grid');if(grid)grid.innerHTML=knowledgeCards();const count=$('#knowledge-count');if(count)count.textContent=knowledgeCount()}
function renderAbout(){return `${header('关于作品','')}<section class="about-hero"><h1>南京河湖<br>监测与分析</h1><p>智水监测是一件水利主题网页作品，包含南京河湖地图、水情模拟和图片识别。水情页可查看水位变化、调整降雨条件；识别页可上传照片，查看分析结果。</p></section><section class="about-section"><h2>功能与流程</h2><div class="pipeline">${[['01','模拟读数','展示水位、流量和 pH，每 3 秒更新一次。'],['02','河湖地图','选择地点后，地图、读数与曲线同步切换。'],['03','图片识别','上传水域照片，查看分析文字和位置标注。'],['04','记录导出','保存巡检记录，导出当前读数或本机台账。']].map(r=>`<article class="feature-card"><span class="number">${r[0]}</span><h3>${r[1]}</h3><p>${r[2]}</p></article>`).join('')}</div></section><section class="about-section"><h2>功能清单与数据说明</h2><div class="scope-grid"><div class="panel scope-panel"><h3>功能清单</h3>${[['水情监测','8 个地点 · 水位、流量、pH'],['降雨模拟','雨强调整 · 时序回放 · 虚拟闸门'],['预警记录','按演示阈值分级 · 处置与撤销'],['图片识别','上传或使用示例 · 结果与原图对照'],['数据导出','模拟读数 CSV · 巡检记录 JSON']].map(r=>`<div class="scope-row"><span>${r[0]}</span><b>${r[1]}</b></div>`).join('')}</div><div class="panel scope-panel"><h3>数据说明</h3><p>地图和照片附有公开来源。水位、流量、pH 和阈值均为教学设定，不是现场读数。图片识别通过云端分析，结果供参考，不能用于防汛调度、水质评价或工程诊断。</p><a class="btn text" href="#/monitor" style="margin-top:15px">查看水情 ${icon('arrow')}</a></div></div></section><section class="about-section"><h2>制作分工</h2><div class="team-grid">${[['设','页面设计','页面布局、字体配色与交互设计。'],['码','前端开发','数据模拟、地图图表和手机适配。'],['水','水利内容','场景设定、基础知识与资料核对。']].map(t=>`<article class="feature-card"><div class="team-avatar">${t[0]}</div><h3>${t[1]}</h3><p>${t[2]}</p></article>`).join('')}</div></section>`}

const waterStories={
  yangtze:{title:'南京长江大桥',subtitle:'一座桥，连接长江两岸的时代记忆',body:[
    '南京长江大桥由我国自主设计、建造，是跨越长江的双层公路铁路桥。1968年9月30日，铁路桥先行通车；同年12月29日，公路桥通车，大桥全线贯通。',
    '这座桥让南来北往的列车与车辆越过江面，也成为南京的城市地标。桥头堡、钢梁与江上航船共同构成了几代人熟悉的长江风景。'
  ],source:'https://dag.nanjing.gov.cn/dawh/dags/202306/t20230616_3939393.html',sourceTitle:'南京市档案馆 · 九年风雨架桥路 大江之上铸丰碑'},
  qinhuai:{title:'夫子庙秦淮河',subtitle:'桨声灯影之间，读一段金陵文脉',body:[
    '秦淮河畔的夫子庙，不只有夜色与灯影。北宋景祐元年（1034年），这里在学宫前建起孔庙；南宋时修筑贡院，逐渐形成孔庙、学宫、贡院相互联系的格局。',
    '这里曾汇聚求学与应试的人群，河岸的街巷也与城市生活交织。1984年起，南京对夫子庙一带开展维修和复建，让沿河建筑与秦淮风光重新走入人们的日常。'
  ],source:'https://dfz.nanjing.gov.cn/gzdt/202511/t20251105_5683339.html',sourceTitle:'南京市地方志工作办公室 · 金陵城垣几更迭 夫子庙堂四度秋',extraSource:'https://www.njqh.gov.cn/dmqh/yzqh/fzmzlg/',extraSourceTitle:'秦淮区人民政府 · 夫子庙展览馆景区历史'},
  xuanwu:{title:'玄武湖',subtitle:'从皇家湖苑到城市山水',body:[
    '玄武湖古称后湖、北湖。六朝时，这里曾是皇家园林湖泊，也曾用于操练水军；到了明代，湖中设立黄册库，保存记载户口与赋役的黄册。',
    '清末，为迎接南洋劝业会，丰润门（今玄武门）被开辟，玄武湖逐渐走向近代公园。从皇家禁苑到市民游赏的湖岸，同一片水面见证了南京城市生活的变迁。'
  ],source:'https://dfz.nanjing.gov.cn/gzdt/202403/t20240307_4181327.html',sourceTitle:'南京市地方志工作办公室 · 照片中的历史：玄武湖的百年变迁',extraSource:'https://www.xwzf.gov.cn/ztzl/szwl/wlzx/202411/t20241112_5006015.html',extraSourceTitle:'玄武区人民政府 · 玄武湖历史文化介绍'}
};
function photoCreditHTML(p){return `<details class="image-credit photo-credit"><summary>图片信息</summary><div class="image-credit-body"><p><a href="${p.source}" target="_blank" rel="noopener">${escapeHTML(decodeURIComponent(p.source.split('/wiki/File:')[1]||p.label).replace(/_/g,' '))}</a></p><p>摄影：${escapeHTML(p.author)} · <a href="${p.licenseUrl}" target="_blank" rel="noopener">${p.license}</a></p><p>${escapeHTML(p.displayChanges)}</p></div></details>`}
function homeDiscovery(){return `<section class="home-discovery" id="home-discovery" aria-label="南京与水利"><button type="button" class="home-discovery-card discovery-city" data-open-gallery aria-haspopup="dialog"><span class="home-discovery-icon" aria-hidden="true">${icon('image')}</span><span class="home-discovery-title">南京实景</span><span class="home-discovery-action">浏览实景 ${icon('arrow')}</span></button><a class="home-discovery-card discovery-knowledge" href="#/knowledge"><span class="home-discovery-icon" aria-hidden="true">${icon('book')}</span><span class="home-discovery-title">水利知识</span><span class="home-discovery-action">阅读文章 ${icon('arrow')}</span></a></section>`}
function coverPhotoSourcesHTML(){const u=aiScenes.ecology;return `<section class="cover-photo-sources"><h3>首页封面照片</h3><p>水域识别：<a href="${u.source}" target="_blank" rel="noopener">红海水下生态</a>，摄影 ${escapeHTML(u.credit)}，<a href="${u.licenseUrl}" target="_blank" rel="noopener">${u.license}</a>。</p><p>封面按版面裁切，叠加渐变蒙层，照片文件未修改。南京实景中的照片署名与许可可在各张照片的信息中查看。</p></section>`}
function openNanjingGallery(focusId){openDialog(`<section class="nanjing-gallery"><h2>南京实景</h2><div class="nanjing-place-grid">${window.HydroAtlas.photos.map(p=>`<button type="button" class="nanjing-place" data-photo-story="${p.id}" aria-haspopup="dialog" aria-label="了解${waterStories[p.id].title}的历史"><img src="${p.file}" alt="${escapeHTML(p.label)}的历史照片" width="640" height="430"><span>${waterStories[p.id].title}${icon('arrow')}</span></button>`).join('')}</div><div class="dialog-actions"><button class="btn" data-close-dialog>返回首页</button></div></section>`);if(focusId)$(`[data-photo-story="${focusId}"]`,$('#dialog-content'))?.focus({preventScroll:true})}
function handlePhotoStoryClick(e){const gallery=e.target.closest('[data-open-gallery]');if(gallery){openNanjingGallery();return true}const back=e.target.closest('[data-story-back]');if(back){openNanjingGallery(back.dataset.storyBack);return true}const story=e.target.closest('[data-photo-story]');if(story){openWaterStory(story.dataset.photoStory,!!story.closest('.nanjing-gallery'));return true}return false}
function openWaterStory(id,fromGallery=false){const story=waterStories[id],p=window.HydroAtlas.photos.find(p=>p.id===id);if(!story||!p)return;openDialog(`<article class="water-story"><img class="water-story-photo" src="${p.file}" alt="${escapeHTML(p.label)}的历史照片" width="640" height="430"><div class="dialog-eyebrow">河湖往事</div><h2>${story.title}</h2><p class="water-story-subtitle">${story.subtitle}</p>${story.body.map(text=>`<p>${text}</p>`).join('')}<details class="water-story-sources"><summary>历史资料来源</summary><a href="${story.source}" target="_blank" rel="noopener">${story.sourceTitle}</a>${story.extraSource?`<a href="${story.extraSource}" target="_blank" rel="noopener">${story.extraSourceTitle}</a>`:''}</details>${photoCreditHTML(p)}<div class="dialog-actions"><button class="btn primary" ${fromGallery?`data-story-back="${id}"`:'data-close-dialog'}>返回实景</button></div></article>`)}
function renderExperience(){return `<div id="journey-host">${window.HydroJourney.render()}</div>`}
function mountGeography(){const target=$('#river-map');if(target&&window.HydroMap){geographicController=new window.HydroMap(target,{stations:visibleStations(),selected:state.selected,layers:state.layers,onSelect:i=>selectStation(i,false,true),statusElement:$('#geo-status'),focusAll:true});if(state.mapMode==='streets')geographicController.setBasemap('streets')}if(state.page==='experience')window.HydroJourney.bind({root:$('#journey-host'),stations,makeMap:(el,options)=>new window.HydroMap(el,options),toast,download});}
function openSources(){openDialog(`<div class="dialog-eyebrow">资料说明</div><h2>数据与图片来源</h2><p><b>真实资料：</b>默认地图使用真实 WGS84 水系、公园和主要道路几何；长江宽水面沿真实中心线示意绘制，不是实测岸线。街道图可按需切换为 OpenStreetMap 底图。地点位置来自对应 OSM 几何或摄影公开坐标；本地水系图层不包含行政界线。</p><p><b>教学模拟：</b>8 个标记是体验定位，不代表官方水文站。水位、流量、pH、阈值与预警均为教学设定，不对应实际水位基准，不用于水情预测或防汛调度。</p><p><b>实景照片：</b>照片来自 Wikimedia Commons，拍摄者与 CC 许可可在各图片的“图片信息”中展开查看。照片不是实时监控，页面仅作版面缩放裁切。</p><p><b>首屏动效：</b>数字河流和地形是概念视觉，不是三维测绘成果。真实地理关系请以地图与来源为参考。</p><div class="article-tip">水系数据时间：${escapeHTML(window.HydroAtlas.geography.timestamp)}。在线底图不可达时，仍会显示本地真实水系轮廓。开放地图可能有遗漏；专业信息请核查权威资料。</div><p><a class="source-link" href="assets/data/nanjing-water.geojson" download>下载本地水系数据（ODbL）</a> · <a class="source-link" href="assets/data/nanjing-context.geojson" download>下载地理背景（ODbL）</a> · <a class="source-link" href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">OSM 署名与 ODbL 许可 <svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-up-right"></use></svg></a> · <a class="source-link" href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener">反馈地图问题 <svg class="inline-arrow" aria-hidden="true" focusable="false" viewBox="0 0 24 24"><use href="assets/ui-icons.svg#arrow-up-right"></use></svg></a></p>${coverPhotoSourcesHTML()}<div class="dialog-actions"><button class="btn primary" data-close-dialog>了解了</button></div>`)}
let homeMotionController=null,sceneController=null,geographicController=null,outlineObserver=null,homeEntrancePlayed=false,suppressHomeEntrance=false,navigationByKeyboard=false,hasRouted=false,pageTransition=null;
function render(){window.HydroDetailCards?.close();window.HydroPollutionView?.destroy();homeMotionController?.destroy();homeMotionController=null;outlineObserver?.disconnect();outlineObserver=null;geographicController?.destroy();geographicController=null;window.HydroJourney?.destroy();sceneController?.destroy();sceneController=null;document.body.dataset.page=state.page;state.chart?.destroy();state.chart=null;$('#main').innerHTML=`<div class="page-enter">${({home:renderHome,monitor:renderMonitor,ai:renderAI,knowledge:renderKnowledge,experience:renderExperience,about:renderAbout}[state.page])()}</div>`;$$('.nav-link,.mobile-tab,.footer-link').forEach(a=>{const active=a.dataset.page===state.page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});document.title=`${navs.find(n=>n[0]===state.page)[2]} · 智水监测`;mountPageOutline();bindPage();if($('#trend-chart'))makeChart();mountGeography();if($('#pollution-workspace'))window.HydroPollutionView?.mount($('#pollution-workspace'));revealSelectedPoint();mountCinematicMotion();applyPaused();syncNotification()}
function mountCinematicMotion(){
  const canvas=$('#digital-river');
  if(!canvas)return;
  if(window.HydroScene)sceneController=new window.HydroScene(canvas,{paused:false,showLabels:false,getReadings:()=>[stations[0].level,stations[3].level,stations[7].level]});
  document.fonts?.ready.then(()=>sceneController?.resize());
  homeMotionController=window.HydroHomeMotion?new window.HydroHomeMotion($('#main'),{entrance:!homeEntrancePlayed&&!suppressHomeEntrance,enabled:!navigationByKeyboard&&!suppressHomeEntrance}):null;
  homeEntrancePlayed=true;
}
function handlePlatformLink(e){
  if(e.defaultPrevented||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;
  const a=e.target.closest('a[href]');if(!a||a.hasAttribute('download')||(a.target&&a.target!=='_self'))return;
  if(!a.getAttribute('href').startsWith('#/'))return;
  window.HydroDetailCards?.close();$('#dialog')?.close();
  if(a.hash!==location.hash)return;
  e.preventDefault();closeSidebar();
  const sectionId=new URLSearchParams(a.hash.split('?')[1]||'').get('section');
  const section=sectionId?document.getElementById(sectionId==='real-water'?'home-discovery':sectionId):null;
  const keyboard=e.detail===0;
  if(section){section.scrollIntoView({behavior:keyboard||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});if(keyboard){section.tabIndex=-1;section.focus({preventScroll:true})}}
  else{window.scrollTo({top:0,behavior:keyboard||matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});if(keyboard)$('#main').focus({preventScroll:true})}
}
function route(){$('#dialog')?.close();const routeValue=location.hash.replace('#/','')||'home',requested=routeValue.split('?')[0],sectionId=new URLSearchParams(routeValue.split('?')[1]||'').get('section'),next=navs.some(n=>n[0]===requested)?requested:'home';closeSidebar();const motion=hasRouted&&next!==state.page&&!navigationByKeyboard&&!matchMedia('(prefers-reduced-motion: reduce)').matches;hasRouted=true;const commit=()=>{if(next==='monitor'){const params=new URLSearchParams(routeValue.split('?')[1]||'');state.monitorTool=['rain','pollution','records'].includes(params.get('tool'))?params.get('tool'):'water';state.monitorSubpage=state.monitorTool==='water'&&['compare','table'].includes(params.get('view'))?params.get('view'):'';if(state.monitorSubpage!=='compare')state.compare=null;}const requestedStation=new URLSearchParams(routeValue.split('?')[1]||'').get('station'),place=stations.find(s=>s.id===requestedStation);if(place&&next==='ai'){state.aiStation=place.index;state.aiSaved=false}if(place&&next==='monitor'){state.selected=place.index;state.region=place.group}if(state.page==='monitor'&&next!=='monitor')state.scenario.playing=false;if(state.page==='ai'&&next!=='ai'&&state.detecting)resetDetection();state.page=next;render();const section=sectionId?document.getElementById(next==='home'&&sectionId==='real-water'?'home-discovery':sectionId):null;if(section?.hasAttribute('data-outline-section'))section.scrollIntoView({behavior:'instant',block:'start'});else window.scrollTo(0,0);if(navigationByKeyboard)$('#main').focus({preventScroll:true})};if(window.HydroPageTransition){pageTransition ||=new window.HydroPageTransition($('#main'),getComputedStyle(document.documentElement).getPropertyValue('--ease-out').trim());pageTransition.run(commit,{motion})}else commit()}
function mountPageOutline(){
 const plans={home:['#home-discovery','#start'],about:['.pipeline','.scope-grid','.team-grid']};
 (plans[state.page]||[]).forEach((selector,i)=>{const match=$(selector),section=state.page==='about'?match?.closest('section'):match;if(section){section.id ||= `${state.page}-section-${i+1}`;section.dataset.outlineSection=''}});
}

