function applyPaused(){homeMotionController?.setPaused(false);sceneController?.setPaused(false);document.body.classList.remove('paused','motion-paused');document.body.classList.toggle('data-paused',state.paused);$$('.refresh-label').forEach(el=>el.textContent=state.scenario.active?(state.scenario.playing?'推演播放中':'推演已暂停'):state.paused?'已暂停':'自动变化');$$('.realtime-toggle').forEach(el=>el.classList.toggle('live-paused',state.paused))}
