function exportCSV(){const rows=[['数据类型','导出时间','站点编号','站点名称','水位(m)','流量(m³/s)','pH','演示阈值(m)','状态'],...visibleStations().map(s=>['前端模拟',new Date().toISOString(),s.id,s.name,s.level,s.flow,s.ph,s.limit,stageInfo(s).name])];download('\uFEFF'+rows.map(r=>r.join(',')).join('\r\n'),'智水监测-模拟数据.csv','text/csv;charset=utf-8');toast(`已导出 ${visibleStations().length} 个站点的模拟数据`)}
function download(data,name,type){const url=URL.createObjectURL(new Blob([data],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function resetDetection(){state.aiRequest++;state.aiController?.abort();state.aiController=null;state.aiDone=false;state.aiSaved=false;state.aiNeedsReview=false;state.aiSummary='';state.aiRejected='';clearTimeout(state.detectionTimer);state.aiTimers.forEach(clearTimeout);state.aiTimers=[];state.detectionTimer=null;state.detecting=false;state.aiPhase=0;state.results=[];state.aiSelection=0;state.aiThreshold=0;}
function releaseImage(){if(state.image?.startsWith('blob:'))URL.revokeObjectURL(state.image)}
function aiFeedback(message){state.aiNotice=message;toast(message);if(state.page==='ai'){const notice=$('#ai-feedback');if(notice){notice.textContent=message;notice.classList.toggle('has-message',!!message)}}}
function loadSample(scene=state.aiScene){if(!aiScenes[scene])scene='ecology';state.uploadToken++;resetDetection();releaseImage();state.aiScene=scene;state.image=aiScenes[scene].file;state.sample=true;state.aiFile=null;state.aiView='annotated';state.aiNotice='';if(state.page==='ai')render()}
async function uploadImage(e){const file=e.target.files?.[0];if(file)await acceptImage(file);e.target.value=''}
async function acceptImage(file){if(!['image/jpeg','image/png','image/webp'].includes(file.type)){aiFeedback('请选择 JPG、PNG 或 WebP 图片，当前画面已保留。');return}if(file.size>10*1024*1024){aiFeedback('图片超过 10 MB，请选择较小的图片，当前画面已保留。');return}const token=++state.uploadToken,url=URL.createObjectURL(file),image=new Image();image.src=url;try{await image.decode();if(token!==state.uploadToken){URL.revokeObjectURL(url);return}resetDetection();releaseImage();state.image=url;state.sample=false;state.aiView='annotated';state.aiFile={name:file.name||'本地图片',width:image.naturalWidth||0,height:image.naturalHeight||0,bytes:file.size};state.aiNotice='';if(state.page==='ai')render()}catch{URL.revokeObjectURL(url);if(token===state.uploadToken)aiFeedback('无法读取这张图片，请选择有效的 JPG、PNG 或 WebP 文件。')}}
function fitDetectionOverlay(){const img=$('#preview-image'),overlay=$('#detection-overlay'),stage=$('#detection-stage');if(!img||!overlay||!stage)return;const fit=()=>{if(!img.naturalWidth)return;const scale=Math.min(stage.clientWidth/img.naturalWidth,stage.clientHeight/img.naturalHeight),w=img.naturalWidth*scale,h=img.naturalHeight*scale;Object.assign(overlay.style,{width:w+'px',height:h+'px',left:(stage.clientWidth-w)/2+'px',top:(stage.clientHeight-h)/2+'px',right:'auto',bottom:'auto'})};if(img.complete)fit();else img.addEventListener('load',fit,{once:true})}
